{"id":"edb78258-102b-41da-9d3a-f0a2e16ab852","inserted_at":"2026-07-08T22:24:40.25984+00:00","updated_at":"2026-07-08T22:24:40.25984+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- ============================================================\r\n-- SCRIPT DEFINITIVO: GAMIFICATION ECONOMICS, CO2 & DaaS (POSTGIS)\r\n-- ============================================================\r\n\r\n-- 1. AGGIORNAMENTO SCHEMA 'scans' (PostGIS)\r\nALTER TABLE scans ADD COLUMN IF NOT EXISTS mobility_type TEXT DEFAULT 'walk';\r\nALTER TABLE scans ADD COLUMN IF NOT EXISTS coords GEOGRAPHY(POINT, 4326);\r\nALTER TABLE scans ADD COLUMN IF NOT EXISTS tenant_id TEXT DEFAULT 'taranto'; \r\n\r\n-- (Nota per la Fase 4: Quando migreremo definitivamente la tabella territories in tenants, \r\n--  attiveremo un trigger BEFORE INSERT su scans che usa ST_Within(coords::geometry, boundaries) \r\n--  per iniettare dinamicamente il tenant_id senza fidarsi del client).\r\n\r\n\r\n-- 2. CALCOLO CO2 E PTI TURISTICO (Trigger su scans)\r\n-- +10 PTI fissi per scansione\r\n-- CO2: walk (0.12), bike (0.10), public (0.08)\r\nCREATE OR REPLACE FUNCTION process_scan_esg_and_pti()\r\nRETURNS TRIGGER AS $$\r\nDECLARE\r\n    last_scan_time TIMESTAMP;\r\n    time_diff_minutes FLOAT;\r\n    estimated_km NUMERIC;\r\n    co2_coeff NUMERIC;\r\n    calculated_co2 NUMERIC;\r\nBEGIN\r\n    SELECT MAX(created_at) INTO last_scan_time\r\n    FROM scans\r\n    WHERE user_id = NEW.user_id AND id != NEW.id;\r\n\r\n    IF last_scan_time IS NULL THEN\r\n        estimated_km := 0.5;\r\n    ELSE\r\n        time_diff_minutes := EXTRACT(EPOCH FROM (NEW.created_at - last_scan_time)) / 60;\r\n        IF time_diff_minutes > 5 THEN\r\n            estimated_km := 0.5;\r\n        ELSE\r\n            estimated_km := 0.2;\r\n        END IF;\r\n    END IF;\r\n\r\n    CASE NEW.mobility_type\r\n        WHEN 'bike' THEN co2_coeff := 0.10;\r\n        WHEN 'public' THEN co2_coeff := 0.08;\r\n        ELSE co2_coeff := 0.12; \r\n    END CASE;\r\n\r\n    calculated_co2 := estimated_km * co2_coeff;\r\n\r\n    UPDATE profiles\r\n    SET \r\n        total_tokens = COALESCE(total_tokens, 0) + 10,\r\n        total_co2 = COALESCE(total_co2, 0) + calculated_co2\r\n    WHERE id = NEW.user_id;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\nDROP TRIGGER IF EXISTS trigger_scan_esg_pti ON scans;\r\nCREATE TRIGGER trigger_scan_esg_pti\r\n    AFTER INSERT ON scans\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION process_scan_esg_and_pti();\r\n\r\n\r\n-- 3. CALCOLO PTI CIVICO (Trigger su civic_reports - Due Testimoni)\r\n-- +50 PTI a tutti i testimoni quando confermato\r\nCREATE OR REPLACE FUNCTION award_civic_pti()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n    IF NEW.status = 'confirmed' AND OLD.status = 'pending_match' THEN\r\n        UPDATE profiles SET total_tokens = COALESCE(total_tokens, 0) + 50 WHERE id = NEW.user_id;\r\n        \r\n        UPDATE profiles SET total_tokens = COALESCE(total_tokens, 0) + 50\r\n        WHERE id IN (\r\n            SELECT user_id FROM civic_reports \r\n            WHERE grid_cell_50m = NEW.grid_cell_50m \r\n            AND id != NEW.id \r\n            AND status = 'confirmed'\r\n        );\r\n    END IF;\r\n\r\n    IF NEW.status = 'resolved' AND OLD.status != 'resolved' THEN\r\n        UPDATE profiles SET total_tokens = COALESCE(total_tokens, 0) + 100 WHERE id = NEW.user_id;\r\n    END IF;\r\n\r\n    RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql;\r\n\r\nDROP TRIGGER IF EXISTS trigger_award_civic_pti ON civic_reports;\r\nCREATE TRIGGER trigger_award_civic_pti\r\n    AFTER UPDATE OF status ON civic_reports\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION award_civic_pti();\r\n\r\n\r\n-- 4. DAAS: HEATMAP GDPR COMPLIANT CON POSTGIS (ST_SnapToGrid)\r\n-- La Materialized View scatta fotografie (snap) raggruppate per intervalli.\r\nCREATE MATERIALIZED VIEW IF NOT EXISTS heatmap_15min_grid AS\r\nSELECT \r\n  tenant_id,\r\n  ST_Y(ST_SnapToGrid(coords::geometry, 0.001)) AS grid_lat,  -- Griglia geospaziale perfetta (~110m)\r\n  ST_X(ST_SnapToGrid(coords::geometry, 0.001)) AS grid_lng,\r\n  DATE_TRUNC('hour', created_at) + INTERVAL '15 min' * (EXTRACT(minute FROM created_at)::int / 15) AS time_block,\r\n  COUNT(DISTINCT user_id) AS unique_users,\r\n  COUNT(*) AS total_scans\r\nFROM scans\r\nWHERE coords IS NOT NULL\r\nGROUP BY tenant_id, grid_lat, grid_lng, time_block;\r\n\r\nCREATE OR REPLACE FUNCTION refresh_heatmap()\r\nRETURNS void AS $$\r\nBEGIN\r\n  REFRESH MATERIALIZED VIEW CONCURRENTLY heatmap_15min_grid;\r\nEND;\r\n$$ LANGUAGE plpgsql;","content_id":"edb78258-102b-41da-9d3a-f0a2e16ab852","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
